1	//! Configuration file discovery and loading.
2	//!
3	//! This module handles finding and loading configuration files from
4	//! various locations in the correct priority order.
5	
6	use crate::config::discovery::Discovery;
7	use crate::config::extends::ExtendsResolver;
8	use crate::config::merger::merge_configs;
9	use crate::config::schema::{BivvyConfig, StepConfig, WorkflowConfig, WorkflowFile};
10	use crate::config::trust::{TrustPolicy, TrustStore};
11	use crate::error::{BivvyError, Result};
12	use crate::ui::{Prompt, PromptResult, PromptType, Prompter};
13	use std::fs;
14	use std::path::{Path, PathBuf};
15	
16	/// Selects which workflow files participate in a merge.
17	///
18	/// `bivvy run` only merges the named workflow file, while `bivvy config
19	/// --merged` (and the legacy `load_merged_config` entry point) merge all
20	/// of them.
21	#[derive(Debug, Clone)]
22	#[allow(dead_code)]
23	enum WorkflowSelection<'a> {
24	    /// Include every workflow file under `.bivvy/workflows/`.
25	    All,
26	    /// Include only the workflow file matching the given filename stem.
27	    One(&'a str),
28	    /// Include no workflow files (used by per-target lint paths).
29	    None,
30	}
31	
32	/// Paths to configuration files in priority order (later overrides earlier).
33	///
34	/// Merge order:
35	/// 1. Remote base configs (from `extends:`)
36	/// 2. User global config (`~/.bivvy/config.yml`)
37	/// 3. Project config (`.bivvy/config.yml`)
38	/// 4. Split-file steps (`.bivvy/steps/*.yml`)
39	/// 5. Split-file workflows (`.bivvy/workflows/*.yml`)
40	/// 6. Local overrides (`.bivvy/config.local.yml`)
41	#[derive(Debug, Clone)]
42	pub struct ConfigPaths {
43	    /// Remote base config (if extends: is used)
44	    pub extends: Vec<PathBuf>,
45	
46	    /// User's global config: ~/.bivvy/config.yml
47	    pub user_global: Option<PathBuf>,
48	
49	    /// Project config: .bivvy/config.yml
50	    pub project: Option<PathBuf>,
51	
52	    /// Split-file step definitions: .bivvy/steps/*.yml
53	    pub split_steps: Vec<PathBuf>,
54	
55	    /// Split-file workflow definitions: .bivvy/workflows/*.yml
56	    pub split_workflows: Vec<PathBuf>,
57	
58	    /// Local overrides: .bivvy/config.local.yml
59	    pub project_local: Option<PathBuf>,
60	}
61	
62	impl ConfigPaths {
63	    /// Discover config files for the given project root.
64	    pub fn discover(project_root: &Path) -> Self {
65	        Self {
66	            extends: Vec::new(), // Populated later after parsing project config
67	            user_global: Self::find_user_global(),
68	            project: Self::find_project_config(project_root),
69	            split_steps: Self::find_split_files(project_root, "steps"),
70	            split_workflows: Self::find_split_files(project_root, "workflows"),
71	            project_local: Self::find_project_local(project_root),
72	        }
73	    }
74	
75	    /// Find user's global config at ~/.bivvy/config.yml
76	    fn find_user_global() -> Option<PathBuf> {
77	        let path = crate::sys::home_dir()?.join(".bivvy").join("config.yml");
78	        if path.exists() {
79	            Some(path)
80	        } else {
81	            None
82	        }
83	    }
84	
85	    /// Find project config at .bivvy/config.yml
86	    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
87	        let path = project_root.join(".bivvy").join("config.yml");
88	        if path.exists() {
89	            Some(path)
90	        } else {
91	            None
92	        }
93	    }
94	
95	    /// Find local overrides at .bivvy/config.local.yml
96	    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
97	        let path = project_root.join(".bivvy").join("config.local.yml");
98	        if path.exists() {
99	            Some(path)
100	        } else {
101	            None
102	        }
103	    }
104	
105	    /// Find YAML files in `.bivvy/<subdir>/`.
106	    ///
107	    /// Returns sorted paths for deterministic merge order.
108	    fn find_split_files(project_root: &Path, subdir: &str) -> Vec<PathBuf> {
109	        let dir = project_root.join(".bivvy").join(subdir);
110	        if !dir.is_dir() {
111	            return Vec::new();
112	        }
113	
114	        let mut files: Vec<PathBuf> = fs::read_dir(&dir)
115	            .into_iter()
116	            .flatten()
117	            .filter_map(|entry| entry.ok())
118	            .map(|entry| entry.path())
119	            .filter(|path| {
120	                path.extension()
121	                    .is_some_and(|ext| ext == "yml" || ext == "yaml")
122	            })
123	            .collect();
124	
125	        files.sort();
126	        files
127	    }
128	
129	    /// Returns all existing config paths in merge order (excludes split files).
130	    pub fn all_existing(&self) -> Vec<&PathBuf> {
131	        let mut paths = Vec::new();
132	
133	        for p in &self.extends {
134	            paths.push(p);
135	        }
136	
137	        if let Some(p) = &self.user_global {
138	            paths.push(p);
139	        }
140	
141	        if let Some(p) = &self.project {
142	            paths.push(p);
143	        }
144	
145	        if let Some(p) = &self.project_local {
146	            paths.push(p);
147	        }
148	
149	        paths
150	    }
151	
152	    /// Check if any project config exists.
153	    ///
154	    /// Returns true if `.bivvy/config.yml` exists OR if any split-file
155	    /// steps/workflows are present.
156	    pub fn has_project_config(&self) -> bool {
157	        self.project.is_some() || !self.split_steps.is_empty() || !self.split_workflows.is_empty()
158	    }
159	
160	    /// Whether any split files were discovered.
161	    pub fn has_split_files(&self) -> bool {
162	        !self.split_steps.is_empty() || !self.split_workflows.is_empty()
163	    }
164	}
165	
166	/// Ensure the global config directory, config file, and schema exist.
167	///
168	/// Creates `~/.bivvy/config.yml` (with commented-out examples) and
169	/// `~/.bivvy/schema.json` if they don't already exist. Called on every
170	/// invocation so every install path (Homebrew, `cargo install`,
171	/// `install.sh`) gets the global config without relying on the installer.
172	///
173	/// The schema file is always rewritten so it stays current after upgrades.
174	///
175	/// Failures are silently ignored — a missing global config is not fatal.
176	pub fn ensure_global_config() {
177	    let Some(home) = crate::sys::home_dir() else {
178	        return;
179	    };
180	    ensure_global_config_in(home);
181	}
182	
183	/// Inner implementation that accepts an explicit home directory.
184	///
185	/// Separated from [`ensure_global_config`] so tests can point at a temp dir.
186	fn ensure_global_config_in(home: PathBuf) {
187	    let bivvy_dir = home.join(".bivvy");
188	
189	    if fs::create_dir_all(&bivvy_dir).is_err() {
190	        return;
191	    }
192	
193	    // Write schema.json on every run so it stays current after upgrades.
194	    let schema_path = bivvy_dir.join("schema.json");
195	    let _ = fs::write(&schema_path, crate::lint::schema_json());
196	
197	    // Only create config.yml if it doesn't exist yet.
198	    let config_path = bivvy_dir.join("config.yml");
199	    if !config_path.exists() {
200	        let schema_display = schema_path.display();
201	        let content = format!(
202	            "\
203	# yaml-language-server: $schema={schema_display}
204	#
205	# Bivvy global configuration
206	# Docs: https://bivvy.dev/configuration
207	#
208	# Settings here apply to ALL projects on this machine.
209	# Project-level .bivvy/config.yml overrides these defaults.
210	
211	# settings:
212	#   defaults:
213	#     output: verbose        # verbose | quiet | silent
214	#     auto_run: true         # auto-run steps or prompt first
215	#     prompt_on_rerun: false # prompt before re-running completed steps
216	#   parallel: false          # enable parallel step execution
217	#   max_parallel: 4          # max concurrent steps (when parallel: true)
218	#   auto_update: true        # check for bivvy updates in the background
219	#   logging: false           # enable JSONL event logging
220	"
221	        );
222	
223	        let _ = fs::write(&config_path, content);
224	    }
225	}
226	
227	/// Find the project root by walking up from current directory.
228	///
229	/// Looks for:
230	/// 1. `.bivvy` directory (primary indicator)
231	/// 2. `.git` directory (fallback)
232	///
233	/// # Returns
234	///
235	/// The path to the project root, or None if not found.
236	pub fn find_project_root(start: &Path) -> Option<PathBuf> {
237	    let mut current = start.to_path_buf();
238	
239	    loop {
240	        // Check for .bivvy directory
241	        if current.join(".bivvy").is_dir() {
242	            return Some(current);
243	        }
244	
245	        // Check for .git directory (fallback)
246	        if current.join(".git").exists() {
247	            return Some(current);
248	        }
249	
250	        // Move up one directory
251	        if !current.pop() {
252	            return None;
253	        }
254	    }
255	}
256	
257	/// Load a single config file and parse it into BivvyConfig.
258	///
259	/// # Errors
260	///
261	/// Returns `ConfigNotFound` if the file doesn't exist.
262	/// Returns `ConfigParseError` if the YAML is invalid.
263	pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
264	    let content = fs::read_to_string(path).map_err(|e| {
265	        if e.kind() == std::io::ErrorKind::NotFound {
266	            BivvyError::ConfigNotFound {
267	                path: path.to_path_buf(),
268	            }
269	        } else {
270	            BivvyError::Io(e)
271	        }
272	    })?;
273	
274	    parse_config(&content, path)
275	}
276	
277	/// Parse YAML content into BivvyConfig.
278	///
279	/// # Arguments
280	///
281	/// * `content` - The YAML content to parse
282	/// * `source_path` - Path for error reporting
283	pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
284	    serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
285	        path: source_path.to_path_buf(),
286	        message: e.to_string(),
287	    })
288	}
289	
290	/// Load a config file as raw YAML Value (for merging).
291	///
292	/// Returns the raw serde_yaml::Value without deserializing into
293	/// BivvyConfig, which allows for deep merging before final parsing.
294	pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
295	    let content = fs::read_to_string(path).map_err(|e| {
296	        if e.kind() == std::io::ErrorKind::NotFound {
297	            BivvyError::ConfigNotFound {
298	                path: path.to_path_buf(),
299	            }
300	        } else {
301	            BivvyError::Io(e)
302	        }
303	    })?;
304	
305	    serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
306	        path: path.to_path_buf(),
307	        message: e.to_string(),
308	    })
309	}
