397	/// Read a step file from disk and parse it into a [`StepConfig`].
398	///
399	/// Step files are simpler than workflow files — they have only one shape.
400	pub fn load_single_step_file(path: &Path) -> Result<StepConfig> {
401	    let content = fs::read_to_string(path).map_err(|e| {
402	        if e.kind() == std::io::ErrorKind::NotFound {
403	            BivvyError::ConfigNotFound {
404	                path: path.to_path_buf(),
405	            }
406	        } else {
407	            BivvyError::Io(e)
408	        }
409	    })?;
