                    message.contains("comand"),
                    "error should mention the unknown field, got: {}",
                    message
                );
                assert!(
                    message.contains("hello"),
                    "error should mention the step name, got: {}",
                    message
                );
            }
            other => panic!("expected ConfigParseError, got: {:?}", other),
        }
    }

    #[test]
    fn parse_config_accepts_all_known_settings_fields() {
        let yaml = r#"
app_name: test
settings:
  parallel: true
  max_parallel: 8
  logging: true
  log_retention_days: 7
  log_retention_mb: 100
  history_retention: 25
  auto_update: false
  diagnostic_funnel: false
  default_rerun_window: "4h"
  env:
    FOO: bar
  env_file: .env
  secret_env:
    - SECRET_KEY
  default_environment: production
  environments:
    ci:
      default_workflow: quick
  defaults:
    output: quiet
"#;
        let result = parse_config(yaml, Path::new("test.yml"));
        assert!(result.is_ok(), "valid settings should parse: {:?}", result.err());
    }

    #[test]
    fn parse_config_accepts_all_known_step_fields() {
        let yaml = r#"
app_name: test
steps:
  hello:
    command: echo hello
    check:
      type: execution
      command: "exit 0"
    retry: 2
    skippable: false
    required: true
    env:
      FOO: bar
    env_file: .env
    env_file_optional: true
    required_env:
      - FOO
    before:
      - echo before
    after:
      - echo after
    allow_failure: true
    sensitive: false
    depends_on:
      - other
    tools:
      - node
    rerun_window: "4h"
    only_environments:
      - ci
"#;
        let result = parse_config(yaml, Path::new("test.yml"));
        assert!(result.is_ok(), "valid step fields should parse: {:?}", result.err());
    }

    #[test]
    fn parse_config_rejects_multiple_unknown_fields() {
        let yaml = "app_name: test\nsettings:\n  paralelll: true\n  loging: false\n";
        let result = parse_config(yaml, Path::new("test.yml"));
        assert!(result.is_err());
        let err = result.unwrap_err();
        match &err {
            BivvyError::ConfigParseError { message, .. } => {
                assert!(message.contains("paralelll"), "got: {}", message);
                assert!(message.contains("loging"), "got: {}", message);
            }
            other => panic!("expected ConfigParseError, got: {:?}", other),
        }
    }

    #[test]
    fn load_merged_config_rejects_unknown_fields() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(
            bivvy_dir.join("config.yml"),
            "app_name: test\nsteps:\n  hello:\n    comand: echo hello\n",
        )
        .unwrap();

        let result = load_merged_config(temp.path());
        assert!(result.is_err(), "merged config should reject unknown fields");
        let err = result.unwrap_err();
        match &err {
            BivvyError::ConfigParseError { message, .. } => {
                assert!(message.contains("comand"), "got: {}", message);
            }
            other => panic!("expected ConfigParseError, got: {:?}", other),
        }
    }
}

