44	    /// Apply fixes from diagnostics that support auto-fix.
45	    pub fn apply_fixes(&self, diagnostics: &[LintDiagnostic], fixes: &[Fix]) -> FixResult {
46	        let mut applied = 0;
47	        let mut errors = Vec::new();
48	
49	        // Group fixes by file
50	        let mut fixes_by_file: HashMap<&Path, Vec<&Fix>> = HashMap::new();
51	        for fix in fixes {
52	            fixes_by_file
53	                .entry(fix.file.as_path())
54	                .or_default()
55	                .push(fix);
56	        }
57	
58	        // Apply fixes to each file
59	        for (file, file_fixes) in fixes_by_file {
60	            match self.apply_fixes_to_file(file, &file_fixes) {
61	                Ok(count) => applied += count,
62	                Err(e) => errors.push(format!("{}: {}", file.display(), e)),
63	            }
64	        }
65	
66	        // Collect unfixable diagnostics
67	        let unfixable = diagnostics
68	            .iter()
69	            .filter(|d| d.suggestion.is_none())
70	            .cloned()
71	            .collect();
72	
73	        FixResult {
74	            applied,
75	            unfixable,
76	            errors,
77	        }
78	    }
79	
80	    /// Preview fixes without applying them.
81	    pub fn preview_fixes(&self, fixes: &[Fix]) -> Vec<String> {
82	        fixes
83	            .iter()
84	            .map(|f| {
85	                format!(
86	                    "{}:{}-{}: Replace with '{}'",
87	                    f.file.display(),
88	                    f.start,
89	                    f.end,
90	                    f.replacement
91	                )
92	            })
93	            .collect()
94	    }
95	
96	    fn apply_fixes_to_file(&self, file: &Path, fixes: &[&Fix]) -> Result<usize, String> {
97	        let content =
98	            fs::read_to_string(file).map_err(|e| format!("Failed to read file: {}", e))?;
99	
100	        // Sort fixes by start position (reverse order for safe replacement)
101	        let mut sorted_fixes = fixes.to_vec();
102	        sorted_fixes.sort_by(|a, b| b.start.cmp(&a.start));
103	
104	        let mut new_content = content;
105	        for fix in &sorted_fixes {
106	            if fix.start <= new_content.len() && fix.end <= new_content.len() {
107	                new_content = format!(
108	                    "{}{}{}",
109	                    &new_content[..fix.start],
110	                    &fix.replacement,
111	                    &new_content[fix.end..]
112	                );
113	            }
114	        }
115	
116	        fs::write(file, new_content).map_err(|e| format!("Failed to write file: {}", e))?;
117	
118	        Ok(sorted_fixes.len())
119	    }
120	}
